export default function ConnectionsPage() {
  const [market,setMarket] = useState<"INDIA"|"CRYPTO">("INDIA");
  const [selected,setSelected] = useState<string>("ZERODHA");
  const [query,setQuery] = useState("");
  const [credentials,setCredentials] = useState<Record<string,string>>({});
  const [saving,setSaving] = useState(false);
  const [verifyingId,setVerifyingId] = useState<string | null>(null);
  const [oauthStartingId,setOauthStartingId] = useState<string | null>(null);
  const [connectionMessage,setConnectionMessage] = useState("");
  const [connections,setConnections] = useState<Connection[]>([]);
  async function loadConnections() {
    try { const response=await fetch("/api/v1/brokers/connections",{credentials:"include"}); if(response.ok){const data=await response.json();setConnections(data.connections ?? []);} } catch { /* Account list remains unavailable until API recovers. */ }
  }
  useEffect(()=>{void loadConnections();},[]);
  async function removeConnection(id:string) {
    const response=await fetch(`/api/v1/brokers/connections/${id}`,{method:"DELETE",credentials:"include",headers:{"content-type":"application/json"}});
    const data=await response.json().catch(()=>({}));
    if(!response.ok){setConnectionMessage(data.error ?? "Unable to disconnect account.");return;}
    await loadConnections();
  }
  async function verifyConnection(id:string) {
    setVerifyingId(id); setConnectionMessage("");
    try {
      const response=await fetch(`/api/v1/brokers/connections/${id}/verify`,{method:"POST",credentials:"include",headers:{"content-type":"application/json"}});
      const data=await response.json().catch(()=>({}));
      if(!response.ok) throw new Error(data.error ?? "Unable to verify broker connection.");
      setConnectionMessage(data.message ?? "Broker authentication verified.");
      await loadConnections();
    } catch(error) {
      setConnectionMessage(error instanceof Error ? error.message : "Unable to verify broker connection.");
      await loadConnections();
    } finally { setVerifyingId(null); }
  }
  async function startOAuth(id:string) {
    setOauthStartingId(id); setConnectionMessage("");
    try {
      const response=await fetch(`/api/v1/brokers/connections/${id}/oauth/start`,{method:"POST",credentials:"include",headers:{"content-type":"application/json"}});
      const data=await response.json().catch(()=>({}));
      if(!response.ok || typeof data.authorizationUrl!=="string") throw new Error(data.error ?? "Unable to start broker login.");
      window.location.assign(data.authorizationUrl);
    } catch(error) {
      setConnectionMessage(error instanceof Error ? error.message : "Unable to start broker login.");
      setOauthStartingId(null);
    }
  }
  const list = useMemo(()=>BROKERS.filter(b=>b.market===market && (b.name.toLowerCase().includes(query.toLowerCase()) || b.id.toLowerCase().includes(query.toLowerCase()))),[market,query]);
  const broker = BROKERS.find(b=>b.id===selected && b.market===market) ?? list[0];
  const credentialDefinitions: Record<string,string[]> = {
    ZERODHA:["apiKey","apiSecret"], ANGEL_ONE:["apiKey"],
    UPSTOX:["clientId","clientSecret"], FYERS:["clientId","clientSecret"],
    SHOONYA:["clientId","clientSecret"], FLATTRADE:["apiKey","apiSecret"],
    FIVE_PAISA:["clientId","clientSecret"], ICICI_BREEZE:["apiKey","apiSecret"],
    ALICE_BLUE:["clientId","apiSecret"], DHAN:["clientId","apiKey","apiSecret"],
    GROWW:["accessToken"], DELTA_INDIA:["apiKey","apiSecret"]
  };
  const credentialKeys = !broker || broker.status !== "DOCUMENTED" ? [] : (credentialDefinitions[broker.id] ?? []);
  // Keep the broker's own portal/API terminology visible while mapping each
  // value to a stable Salts payload key. Never infer one provider's labels for another.
  const credentialLabels: Record<string,Record<string,string>> = {
    ZERODHA:{apiKey:"Kite Connect API key (api_key)",apiSecret:"Kite Connect API secret (api_secret)"},
    ANGEL_ONE:{apiKey:"SmartAPI app API key (api_key)"},
    UPSTOX:{clientId:"Upstox API key / client ID (client_id)",clientSecret:"Upstox API secret (client_secret)"},
    FYERS:{clientId:"FYERS app ID (app_id)",clientSecret:"FYERS app secret (app_secret)"},
    SHOONYA:{clientId:"Shoonya client ID (exact account/app label to be confirmed against current official flow)",clientSecret:"Shoonya secret code (exact field contract to be confirmed before connection is enabled)"},
    FLATTRADE:{apiKey:"Flattrade API key (api_key)",apiSecret:"Flattrade API secret (api_secret)"},
    FIVE_PAISA:{clientId:"5paisa app key (app_key)",clientSecret:"5paisa encryption key (encryption_key)"},
    ICICI_BREEZE:{apiKey:"Breeze API app key (api_key)",apiSecret:"Breeze API secret key (api_secret)"},
    ALICE_BLUE:{clientId:"Alice Blue app code (appCode)",apiSecret:"Alice Blue API secret (apiSecret)"},
    DHAN:{clientId:"Dhan client ID (client_id)",apiKey:"DhanHQ API key (app_id)",apiSecret:"DhanHQ API secret (app_secret)"},
    GROWW:{accessToken:"Groww Trading API access token (access_token)"},
    DELTA_INDIA:{apiKey:"Delta Exchange API key (api_key)",apiSecret:"Delta Exchange API secret (api_secret)"}
  };
  const labelsForBroker = broker ? credentialLabels[broker.id] ?? {} : {};
  const canSubmitCredentials = credentialKeys.length > 0;
  async function saveCredentials() {
    if (!broker || !credentialKeys.every(key=>(credentials[key] ?? "").trim())) return;
    setSaving(true); setConnectionMessage("");
    try {
      const response = await fetch("/api/v1/brokers/connections", { method:"POST", credentials:"include", headers:{"content-type":"application/json"}, body:JSON.stringify({ provider:broker.id, label:broker.name, credentials:Object.fromEntries(credentialKeys.map(key=>[key,credentials[key]!.trim()])) }) });
      const data = await response.json().catch(()=>({}));
      if (!response.ok) throw new Error(data.error ?? "Unable to save broker credentials.");
      setCredentials({});
      setConnectionMessage(data.message ?? "Credentials saved. Connection is pending verification.");
      await loadConnections();
    } catch (error) { setConnectionMessage(error instanceof Error ? error.message : "Unable to save credentials."); }
    finally { setSaving(false); }
  }
  return <main className="admin-wrap">
    <header className="admin-header"><div><div className="brand">SALTS <span>●</span> COPY DESK</div><p className="eyebrow">ACCOUNT WORKSPACE · BROKER CONNECTIONS</p><h1>Connect a broker</h1><p className="sub">Every user connects their own account. India and Crypto credentials are stored and routed separately.</p></div><div className="header-actions"><a className="text-link" href="/security">Security / MFA</a><a className="text-link" href="/">← Overview</a><LogoutButton /></div></header>
    <div className="market-switch"><button className={market==="INDIA"?"market selected":"market"} onClick={()=>{setMarket("INDIA");setSelected("ZERODHA");setCredentials({});setConnectionMessage("");}}>India brokers</button><button className={market==="CRYPTO"?"market selected":"market"} onClick={()=>{setMarket("CRYPTO");setSelected("DELTA_INDIA");setCredentials({});setConnectionMessage("");}}>Crypto exchanges</button></div>
    <section className="card"><div className="section-head"><div><h2>Your broker accounts</h2><p className="sub">Connection records are private to your login. A host's credentials are never visible to subscribers, and subscriber accounts are never shared with hosts.</p></div><span className="pill">KMS vault required</span></div><p className="sub">API-token connections are submitted only to the server-side AWS KMS envelope vault. If the managed vault is not configured, the API rejects the request without storing credentials. Credential intake is available only for providers with a verified field contract; research-only providers remain disabled. Provider authentication and order routing are separate verification stages. Delta Exchange India has signed read-only account verification. Zerodha, Upstox and FYERS now use broker-hosted login with one-time state-bound callbacks and server-side token exchange. Dhan and other providers remain pending provider-specific authentication implementation.</p>{connections.length===0 ? <p className="sub">No broker connection records yet.</p> : <div className="table-wrap"><table><thead><tr><th>Provider</th><th>Workspace</th><th>Status</th><th>Added</th><th></th></tr></thead><tbody>{connections.map(connection=><tr key={connection.id}><td>{connection.provider} · {connection.label}</td><td>{connection.market}</td><td>{connection.status}</td><td>{new Date(connection.createdAt).toLocaleString()}</td><td>{["ZERODHA","UPSTOX","FYERS"].includes(connection.provider) && <button className="quiet-button" disabled={oauthStartingId===connection.id} onClick={()=>void startOAuth(connection.id)}>{oauthStartingId===connection.id?"Opening broker…":connection.status==="CONNECTED"?"Re-authorize":"Connect account"}</button>} {connection.provider==="DELTA_INDIA" && connection.status!=="CONNECTED" && <button className="quiet-button" disabled={verifyingId===connection.id} onClick={()=>void verifyConnection(connection.id)}>{verifyingId===connection.id?"Verifying…":"Verify account"}</button>} <button className="quiet-button" onClick={()=>void removeConnection(connection.id)}>Disconnect</button></td></tr>)}</tbody></table></div>}<a className="text-link" href="/security">Manage authenticator MFA →</a><br/><a className="text-link" href="/marketplace">Continue to marketplace →</a></section>
    <section className="card">
      <div className="section-head"><div><h2>Choose provider</h2><p className="sub">{market==="INDIA"?"Indian broker integrations":"Crypto exchange integrations"}</p></div><span className="pill">{list.length} researched</span></div>
      <input aria-label="Search providers" placeholder="Search broker or exchange…" value={query} onChange={e=>setQuery(e.target.value)} />
      <div className="listing" style={{display:"flex",flexWrap:"wrap",gap:8,marginTop:14}}>{list.map(b=><button key={b.id} className={selected===b.id?"primary-button":"quiet-button"} onClick={()=>{setSelected(b.id);setCredentials({});setConnectionMessage("");}}>{b.name}</button>)}</div>
    </section>
    {broker && <section className="card">
      <div className="section-head"><div><p className="eyebrow">{broker.market} · {broker.status.replace("_"," ")}</p><h2>{broker.name}</h2><p className="sub">{broker.auth}</p></div><a className="text-link" href={broker.docsUrl} target="_blank" rel="noreferrer">Official documentation ↗</a></div>
      <h3>Credentials the wizard will request</h3><ul>{broker.credentialFields.map(x=><li key={x}>{x}</li>)}</ul>
      <h3>Connection steps</h3><ol>{broker.setup.map(x=><li key={x}>{x}</li>)}</ol>
      <h3>Important limitations</h3><ul>{broker.restrictions.map(x=><li key={x}>{x}</li>)}</ul>
      <h3>Market coverage</h3><p>{broker.segments.join(" · ")}</p><p className="sub">{broker.notes}</p>
      {canSubmitCredentials ? <div className="connection-form"><h3>Secure app-credential intake</h3><p className="sub">Only enter the provider-specific application credentials listed below. Broker login, OTP/TOTP, PIN/MPIN and redirect-returned authorization codes/tokens must be handled in a separate provider-hosted authentication flow; do not enter them here. Values are encrypted server-side with AWS KMS before storage.</p>{credentialKeys.map(key=><label className="admin-label" key={key}>{labelsForBroker[key] ?? key}<input type="password" autoComplete="new-password" value={credentials[key] ?? ""} onChange={event=>setCredentials(current=>({...current,[key]:event.target.value}))} /></label>)}<button className="primary-button" disabled={saving || !credentialKeys.every(key=>(credentials[key] ?? "").trim())} onClick={()=>void saveCredentials()}>{saving ? "Encrypting and saving…" : "Save encrypted app credentials"}</button>{connectionMessage && <p className="sub" role="status">{connectionMessage}</p>}<p className="sub">Saving credentials does not connect or authenticate the broker. The record remains PENDING until OAuth/login, account identity, trading permissions, static-IP and provider health checks pass. Secure storage also requires AWS KMS to be configured.</p></div> : <div className="connection-form"><h3>Connection unavailable — verification pending</h3><p className="sub">We are not collecting credentials for this provider yet. Its official API availability, exact authentication requirements, account eligibility, third-party platform permissions and order capabilities must be verified before enabling a connection form.</p></div>}
    </section>}
    <section className="card"><h2>Security rules</h2><ul><li>Never enter broker passwords, PINs, TOTP seeds or withdrawal credentials into chat, email or support tickets.</li><li>API secrets will be encrypted server-side with a managed key vault; they will never be returned to the browser or written to logs.</li><li>Use read-only permissions where possible; add order permissions only when approved. Withdrawal/transfer permissions are never requested.</li><li>Each connection belongs to one user and one market. India credentials cannot be selected in Crypto, or vice versa.</li><li>Static-IP requirements must be satisfied before order permission is enabled.</li></ul></section>
  </main>;
}
